María Inmaculada, tabernáculo viviente de la Divinidad, donde la Sabiduría eterna está escondida para ser adorada y servida por los ángeles y los hombres, Reina del cielo y de la tierra, bajo cuyo dominio están sometidas todas las cosas inferiores a Dios, Patrona de los Estados Unidos de América, apenados y conscientes de nuestra propia pecaminosidad y de los pecados de nuestra nación, acudimos a ti, nuestro refugio y esperanza.

Sabiendo que nuestro país no puede salvarse por nuestras propias obras y conscientes de cuánto se ha apartado nuestra nación de los caminos de tu Hijo, te pedimos humildemente que vuelvas tus ojos hacia nuestro país para lograr su conversión. Te consagramos la integridad de las próximas elecciones y su resultado, para que se realice lo que sea espiritual y moralmente mejor para los ciudadanos de nuestro país, y para que todos los que sean elegidos gobiernen según los principios espirituales y morales que harán que nuestra nación se conforme con las enseñanzas de tu Hijo.

(menciona tu petición aquí…)

Concede la gracia a los ciudadanos de esta tierra para que elijan gobernantes según el Sagrado Corazón de tu Hijo, a fin de que su gloria se manifieste, y no se nos den los gobernantes que merecemos. Confiando en el cuidado providente de Dios Padre y en tu cuidado maternal, tenemos plena confianza en que cuidarás de nosotros y no nos dejarás desamparados. Oh María Inmaculada, ruega por nosotros.

Amén.

(Nota: esta es una novena de 54 días)

En el nombre del Padre, y del Hijo, y del Espíritu Santo.

Amén.""", """In the Name of the Father, and of the Son, and of the Holy Spirit.

Amen.

Mary Immaculate, living tabernacle of the Divinity, where the eternal Wisdom lies hidden to be adored and served by angels and men, Queen of heaven and of earth, beneath whose sway are subject all things that are lower than God, Patroness of the United States of America, sorrowful and mindful of our own sinfulness and the sins of our nation, we come to Thee, our refuge and hope.

Knowing that our country cannot be saved by our own works and mindful of how much our nation has departed from the ways of Thy Son, we humbly ask that Thou wouldst turn Thine eyes upon our country to bring about its conversion. We consecrate to Thee the integrity of the upcoming election and its outcome, so that what is spiritually and morally best for the citizens of our country may be accomplished, and that all of those who are elected would govern according to the spiritual and moral principles which will bring our nation into conformity with the teachings of Thy Son.

(mention request here…)

Give grace to the citizens of this land so that they will choose leaders according to the Sacred Heart of Thy Son, that His glory may be made manifest, lest we be given the leaders we deserve. Trusting in the providential care of God the Father and Thy maternal care, we have perfect confidence that Thou will take care of us and will not leave us forsaken. O Mary Immaculate, pray for us.

Amen.

(Note: This is a 54 Day Novena)

In the Name of the Father, and of the Son, and of the Holy Spirit.

Amen.""", """Em nome do Pai, do Filho e do Espírito Santo.

Amém.

Maria Imaculada, tabernáculo vivo da Divindade, onde a eterna Sabedoria está escondida para ser adorada e servida pelos anjos e pelos homens, Rainha do céu e da terra, a cujo domínio estão sujeitas todas as coisas inferiores a Deus, Padroeira dos Estados Unidos da América, pesarosos e conscientes da nossa própria pecaminosidade e dos pecados da nossa nação, vimos a vós, nosso refúgio e esperança.

Sabendo que o nosso país não pode ser salvo pelas nossas próprias obras, e conscientes de quanto a nossa nação se afastou dos caminhos do vosso Filho, pedimos humildemente que volteis os vossos olhos para o nosso país, para alcançar a sua conversão. Consagramos a vós a integridade das próximas eleições e o seu resultado, para que se realize o que é espiritual e moralmente melhor para os cidadãos do nosso país, e para que todos os que forem eleitos governem segundo os princípios espirituais e morais que conformarão a nossa nação aos ensinamentos do vosso Filho.

(mencione o pedido aqui…)

Concedei graça aos cidadãos desta terra, para que escolham líderes segundo o Sagrado Coração do vosso Filho, para que a Sua glória se manifeste, e não nos sejam dados os líderes que merecemos. Confiando no cuidado providente de Deus Pai e no vosso cuidado materno, temos plena confiança de que cuidareis de nós e não nos deixareis desamparados. Ó Maria Imaculada, rogai por nós.

Amém.

Observação: esta é uma novena de 54 dias.

Em nome do Pai, do Filho e do Espírito Santo.

Amém."""),
                intentionGuidance = LocalizedText("""""", """""", """""")
            ),
